# Builds the narrated instructional MP4 from REAL application screenshots.
# Requires ffmpeg on PATH and the per-slide MP3 files in assets/narration/
# (generated by make_narration.py). No AI-generated imagery is used.
$ErrorActionPreference = 'Stop'
$assets = Split-Path -Parent $MyInvocation.MyCommand.Path
$screens = Join-Path $assets 'screens'
$cards = Join-Path $assets 'cards'
$narration = Join-Path $assets 'narration'
$out = Join-Path $assets 'instructional.mp4'

$images = @(
  (Join-Path $cards '00-intro.png'),
  (Join-Path $screens '01-landing-en.png'),
  (Join-Path $cards '02-add-coins.png'),
  (Join-Path $screens '03-charity-box.png'),
  (Join-Path $cards '04-choose.png'),
  (Join-Path $screens '04-donate.png'),
  (Join-Path $screens '02-dashboard.png'),
  (Join-Path $cards '06-verify.png'),
  (Join-Path $screens '05-history.png'),
  (Join-Path $cards '09-kiosk.png'),
  (Join-Path $screens '07-kiosk-en.png'),
  (Join-Path $cards '10-outro.png')
)
$count = $images.Count
$transition = 0.5

# Give every spoken line enough screen time, plus a small pause.
$durations = @()
for ($i = 0; $i -lt $count; $i++) {
  $mp3 = Join-Path $narration ('{0:D2}.mp3' -f $i)
  if (-not (Test-Path $mp3)) { throw "Missing narration: $mp3" }
  $spoken = [double](& ffprobe -v error -show_entries format=duration -of csv=p=0 $mp3)
  $slide = [math]::Max(2.6, [math]::Ceiling(($spoken + 0.55) * 10) / 10)
  $durations += $slide
}
$starts = @()
$cursor = 0.0
for ($i = 0; $i -lt $count; $i++) {
  $starts += $cursor
  $cursor += $durations[$i] - $transition
}
$total = $starts[$count - 1] + $durations[$count - 1]
$invariant = [Globalization.CultureInfo]::InvariantCulture

$ffmpegArgs = @('-y', '-hide_banner', '-loglevel', 'error')
for ($i = 0; $i -lt $count; $i++) {
  $t = $durations[$i].ToString('0.0', $invariant)
  $ffmpegArgs += @('-loop', '1', '-t', $t, '-i', $images[$i])
}
for ($i = 0; $i -lt $count; $i++) {
  $ffmpegArgs += @('-i', (Join-Path $narration ('{0:D2}.mp3' -f $i)))
}

$filters = @()
for ($i = 0; $i -lt $count; $i++) {
  $filters += "[$($i):v]fps=24,scale=1280:720:force_original_aspect_ratio=decrease,pad=1280:720:(ow-iw)/2:(oh-ih)/2:color=0x0c2a1e,setsar=1,format=yuv420p[v$i]"
}
$last = 'v0'
for ($i = 1; $i -lt $count; $i++) {
  $offset = $starts[$i].ToString('0.0', $invariant)
  $chain = "x$i"
  $filters += "[$last][v$i]xfade=transition=fade:duration=$($transition.ToString('0.0',$invariant)):offset=$offset[$chain]"
  $last = $chain
}
$filters += "[$last]null[final]"

$audioLabels = @()
for ($i = 0; $i -lt $count; $i++) {
  $inputIndex = $count + $i
  $delayMs = [int](($starts[$i] + 0.15) * 1000)
  $label = "a$i"
  $trim = $durations[$i].ToString('0.0', $invariant)
  $filters += "[$($inputIndex):a]adelay=${delayMs}|${delayMs},atrim=duration=$trim,volume=1.4[$label]"
  $audioLabels += "[$label]"
}
$fadeStart = ($total - 1.2).ToString('0.0', $invariant)
$filters += (($audioLabels -join '') + "amix=inputs=$count`:duration=longest:normalize=0,afade=t=in:st=0:d=0.4,afade=t=out:st=$fadeStart`:d=1.0[audio]")

$ffmpegArgs += @(
  '-filter_complex', ($filters -join ';'),
  '-map', '[final]', '-map', '[audio]',
  '-c:v', 'libx264', '-preset', 'veryfast', '-crf', '27', '-pix_fmt', 'yuv420p',
  '-c:a', 'aac', '-b:a', '96k', '-ar', '44100', '-movflags', '+faststart', $out
)
& ffmpeg @ffmpegArgs
if ($LASTEXITCODE -ne 0) { throw "ffmpeg failed with exit code $LASTEXITCODE" }
Write-Output ("Narrated video: {0:N1}s" -f $total)
Get-Item $out | Select-Object Name, Length
